import sys
import math

MOD = 10**9 + 7

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    N = int(data[0])
    A = list(map(int, data[1:1+N]))

    current_lcm = A[0]
    for i in range(1, N):
        current_lcm = lcm(current_lcm, A[i])

    total = 0
    for a in A:
        total = (total + current_lcm // a) % MOD

    print(total)

if __name__ == "__main__":
    main()
"}

