def get_path(u, v):
    """Find the path from u to v in the binary tree."""
    path = []
    while u != v:
        if u > v:
            path.append((u, u // 2))
            u = u // 2
        else:
            path.append((v, v // 2))
            v = v // 2
    return path

# Read input
q = int(input())
cost = {}  # Dictionary to store road costs

for _ in range(q):
    parts = input().split()
    if parts[0] == '1':
        # Type 1: Increase cost
        v, u, w = int(parts[1]), int(parts[2]), int(parts[3])
        path = get_path(v, u)
        for a, b in path:
            if a > b:  # Road is from smaller to larger
                road = (a, b)
            else:
                road = (b, a)
            cost[road] = cost.get(road, 0) + w
    else:
        # Type 2: Query cost
        v, u = int(parts[1]), int(parts[2])
        path = get_path(v, u)
        total = 0
        for a, b in path:
            if a > b:  # Road is from smaller to larger
                road = (a, b)
            else:
                road = (b, a)
            total += cost.get(road, 0)
        print(total)
