import sys

def cross(p0, p1, p2):
    """Compute cross product (p1 - p0) × (p2 - p0)"""
    return (p1[0] - p0[0]) * (p2[1] - p0[1]) - (p1[1] - p0[1]) * (p2[0] - p0[0])

def dot(p0, p1, p2):
    """Compute dot product (p2 - p0) · (p1 - p0)"""
    return (p2[0] - p0[0]) * (p1[0] - p0[0]) + (p2[1] - p0[1]) * (p1[1] - p0[1])

# Read input
lines = sys.stdin.read().splitlines()
data = list(map(int, lines[0].split()))
xp0, yp0, xp1, yp1 = data

# Convert to tuples for easier math
p0 = (xp0, yp0)
p1 = (xp1, yp1)

# Read queries
q = int(lines[1])
points = []
for line in lines[2:2+q]:
    parts = list(map(int, line.split()))
    points.append((parts[0], parts[1]))

# Process each query
for p2 in points:
    # Compute cross product
    val = cross(p0, p1, p2)

    if val > 0:
        print("COUNTER_CLOCKWISE")
    elif val < 0:
        print("CLOCKWISE")
    else:
        # Collinear case
        # Check if p2 is ONLINE_BACK (before p0)
        if dot(p0, p1, p2) < 0:
            print("ONLINE_BACK")
        # Check if p2 is ONLINE_FRONT (after p1)
        elif dot(p2, p1, p1) < 0:
            print("ONLINE_FRONT")
        # Otherwise, it's ON_SEGMENT
        else:
            print("ON_SEGMENT")
"}

