import sys

def parse_key(description):
    """Parse a key description into a set of coordinates"""
    lines = description.strip().split()
    if not lines:
        return set()

    # First element is the number of elements
    if not lines[0].isdigit():
        return set()
    num_elements = int(lines[0])

    # Remaining elements are the actual path
    elements = lines[1:1+num_elements]

    # Track positions and labels
    positions = {}
    coordinates = set()

    # Start at origin
    current_pos = (0, 0, 0)
    positions[current_pos] = 0

    i = 0
    while i < len(elements):
        token = elements[i]

        if token.isdigit() and int(token) > 0:
            # This is a label
            label = int(token)

            # Check if this label exists
            if current_pos not in positions:
                positions[current_pos] = label
            else:
                # This label defines a new path
                # Start at this position
                current_pos = positions[current_pos]
                positions[current_pos] = label

            i += 1
        else:
            # This is a direction
            direction = token

            # Move along the direction
            if direction == "+x":
                new_pos = (current_pos[0] + 1, current_pos[1], current_pos[2])
            elif direction == "-x":
                new_pos = (current_pos[0] - 1, current_pos[1], current_pos[2])
            elif direction == "+y":
                new_pos = (current_pos[0], current_pos[1] + 1, current_pos[2])
            elif direction == "-y":
                new_pos = (current_pos[0], current_pos[1] - 1, current_pos[2])
            elif direction == "+z":
                new_pos = (current_pos[0], current_pos[1], current_pos[2] + 1)
            elif direction == "-z":
                new_pos = (current_pos[0], current_pos[1], current_pos[2] - 1)
            else:
                # Shouldn't happen
                return set()

            # Add both endpoints to coordinates
            coordinates.add(current_pos)
            coordinates.add(new_pos)

            # Update current position
            current_pos = new_pos

            i += 1

    return coordinates

def normalize(coordinates):
    """Normalize a set of coordinates by translating to origin"""
    if not coordinates:
        return set()

    # Find the minimum coordinate
    min_x = min(p[0] for p in coordinates)
    min_y = min(p[1] for p in coordinates)
    min_z = min(p[2] for p in coordinates)

    # Translate all coordinates
    normalized = set()
    for x, y, z in coordinates:
        normalized.add((x - min_x, y - min_y, z - min_z))

    return normalized

def compare_keys(key1, key2):
    """Compare two keys for equality"""
    if len(key1) != len(key2):
        return False

    for p1, p2 in zip(key1, key2):
        if p1 != p2:
            return False

    return True

def main():
    lines = [line.strip() for line in sys.stdin if line.strip() != '']

    i = 0
    results = []

    while i < len(lines):
        if lines[i] == '0':
            break

        # Read first key description
        key1_elements = lines[i:i+100]
        key1_desc = ' '.join(key1_elements)
        key1_coords = parse_key(key1_desc)

        # Read second key description
        key2_elements = lines[i+1:i+101]
        key2_desc = ' '.join(key2_elements)
        key2_coords = parse_key(key2_desc)

        # Normalize and compare
        if compare_keys(normalize(key1_coords), normalize(key2_coords)):
            results.append('SAME')
        else:
            results.append('DIFFERENT')

        i += 2

    for result in results:
        print(result)

if __name__ == '__main__':
    main()
"}

