    # Translate all coordinates
    normalized = set()
    for x, y, z in coordinates:
        normalized.add((x - min_x, y - min_y, z - min_z))

    return normalized

def compare_keys(key1, key2):
    """Compare two keys for equality"""
    if len(key1) != len(key2):
        return False

    for p1, p2 in zip(key1, key2):
        if p1 != p2:
            return False

    return True

def main():
    lines = [line.strip() for line in sys.stdin if line.strip() != '']

    i = 0
    results = []

    while i < len(lines):
        if lines[i] == '0':
            break

        # Read first key description
        key1_elements = lines[i:i+100]
        key1_desc = ' '.join(key1_elements)
        key1_coords = parse_key(key1_desc)

        # Read second key description
        key2_elements = lines[i+1:i+101]
        key2_desc = ' '.join(key2_elements)
        key2_coords = parse_key(key2_desc)

        # Normalize and compare
        if compare_keys(normalize(key1_coords), normalize(key2_coords)):
            results.append('SAME')
        else:
            results.append('DIFFERENT')

        i += 2

    for result in results:
        print(result)

if __name__ == '__main__':
    main()

