import math

def count_valid_pairs(N):
    """Count the number of valid pairs (a, b) where 1 <= a < b <= N and (a+b) divides (a*b)."""
    answer = 0

    for k in range(1, N + 1):
        k_squared = k * k

        # Find all divisors d of k_squared such that d < sqrt(k_squared)
        for d in range(1, int(math.isqrt(k_squared)) + 1):
            if k_squared % d == 0:
                # Check if d < k_squared/d (to avoid duplicates)
                if d < k_squared // d:
                    a = d + k
                    b = (k_squared // d) + k

                    if a < b and a <= N and b <= N:
                        answer += 1

    return answer

T = int(input())
for _ in range(T):
    N = int(input())
    print(count_valid_pairs(N))
