# Read all comparisons from input
comparisons = []
for line in sys.stdin:
    line = line.strip()
    if line:
        comparisons.append(line)

# Parse comparisons
inequality = {}
for comp in comparisons:
    parts = comp.split('>')
    if len(parts) == 2:
        left, right = parts[0], parts[1]
        inequality[left] = right  # left is heavier than right
    else:
        parts = comp.split('<')
        left, right = parts[0], parts[1]
        inequality[left] = right  # left is lighter than right

# Try all possible orderings of coins
coins = ['A', 'B', 'C']
possible_orderings = []

from itertools import permutations
for perm in permutations(coins):
    # Check if this ordering satisfies all comparisons
    valid = True
    for left, right in inequality.items():
        # In the ordering, left should be heavier than right
        left_pos = perm.index(left)
        right_pos = perm.index(right)
        if left_pos <= right_pos:
            valid = False
            break
    if valid:
        possible_orderings.append(perm)

# Output the result
if len(possible_orderings) == 0:
    print("Impossible")
else:
    # Output one of the valid orderings (we can output the first one)
    print(''.join(possible_orderings[0]))
