def find_y(s, x_set, sum_x):
    """Find a subset Y of blocks not in X such that the equality holds"""

    # We need sum(x) = k * s where k is the size of Y
    # Let's try different values of k
    for k in range(1, s - len(x_set) + 1):
        needed = sum_x - k * s

        # Find k blocks not in X that sum to needed
        available = sorted(set(range(1, s + 1)) - x_set)

        if needed <= sum(available[-k:]):
            # Try to find such a subset
            y = available[-k:]
            if sum(y) == needed:
                return y

            # Adjust by swapping smaller blocks in Y with larger blocks not in X
            # But only if needed > sum of current Y
            # Actually, we need a better approach

            # Simple greedy: keep the largest blocks
            # We need to find any k blocks that sum to needed
            # Let's just use the largest available blocks and adjust

            y = available[-k:]
            current_sum = sum(y)

            # If needed > current_sum, we need to increase the sum
            # So replace the smallest block in Y with a larger block not in X
            if needed > current_sum:
                for i in range(k):
                    for other in available[:k - i]:
                        if other > y[i]:
                            y[i], y[0] = y[0], y[i]
                            if sum(y) == needed:
                                return y

            # If needed < current_sum, we need to decrease the sum
            # So replace the largest block in Y with a smaller block not in X
            else:
                for i in range(k-1, -1, -1):
                    for other in available[k:]:
                        if other < y[i]:
                            y[i], y[k-1] = y[k-1], y[i]
                            if sum(y) == needed:
                                return y

