# DP solution for maximizing correct marching percentage

def solve():
    # Read input
    s = input().strip()

    n = len(s)

    # expected foot at position i (1-indexed)
    expected = []
    for i in range(n):
        # position 1: R, position 2: L, etc.
        if i % 2 == 0:
            expected.append('L')  # even position in 0-indexed
        else:
            expected.append('R')   # odd position in 0-indexed

    # DP[i][last] = (best_total, best_correct) after processing i characters
    # last is the last non-X step ('L', 'R', or None for no step)

    # Initialize: after 0 characters, we've made 0 steps
    dp = {None: (0, 0)}

    for i in range(n):
        c = s[i]
        new_dp = {}

        for last in dp:
            total, correct = dp[last]

            # Option 1: keep the current character as is
            if c != 'X':
                # Check if we can use this character
                if last is None:
                    # No previous step, we start with this step
                    new_total = total + 1
                    if c == expected[i]:
                        new_correct = correct + 1
                    else:
                        new_correct = correct

                    # Update DP
                    if new_total not in new_dp or new_dp[new_total] < new_correct:
                        new_dp[new_total] = new_correct
                else:
                    # Check if we can use this character without a break
                    if c != last:
                        new_total = total + 1
                        if c == expected[i]:
                            new_correct = correct + 1
                        else:
                            new_correct = correct

                        # Update DP
                        if new_total not in new_dp or new_dp[new_total] < new_correct:
                            new_dp[new_total] = new_correct
                    else:
                        # Can't use this character without a break
                        pass

            # Option 2: add a break (X) before this character
            # This effectively skips the current character
            if c == 'X':
                # We can add a break before this character
                # So the current character is just a break
                new_total = total + 1
                new_correct = correct

                # Update DP
                if new_total not in new_dp or new_dp[new_total] < new_correct:
                    new_dp[new_total] = new_correct

        dp = new_dp

    # After processing all characters, we might want to add more breaks at the end
    # to make sure we don't have consecutive steps without a break

    best_percentage = 0
    for total, correct in dp.values():
        percentage = (correct / total) * 100 if total > 0 else 0
        best_percentage = max(best_percentage, percentage)

    print(f"{best_percentage:.6f}")

if __name__ == "__main__":
    solve()
"}

