import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Read matrix t
    t = []
    for i in range(3):
        row = list(map(int, data[i*3:(i+1)*3]))
        t.append(row)

    # Read number of disks n
    n = int(data[9])

    # dp[i][A][C] = minimal cost to move i disks from rod A to rod C
    # Rods are 1, 2, 3

    # Base case: moving 1 disk from A to C
    dp = [[[0]*4 for _ in range(4)] for _ in range(n+1)]  # dp[i][A][C]
    for A in range(1, 4):
        for C in range(1, 4):
            if A == C:
                continue
            dp[1][A][C] = t[A-1][C-1]

    # Fill dp table
    for i in range(2, n+1):
        for A in range(1, 4):
            for C in range(1, 4):
                if A == C:
                    continue

                # B is the rod not A or C
                B = 6 - A - C

                # Option 1: Use B as auxiliary
                option1 = dp[i-1][A][B] + t[A-1][C-1] + dp[i-1][B][C]

                # Option 2: Use A as auxiliary (move n-1 from A to C, then 1 from A to B, then n-1 from C to B)
                option2 = dp[i-1][A][C] + t[A-1][B-1] + dp[i-1][C][B]

                # Choose the minimum cost
                dp[i][A][C] = min(option1, option2)

    print(dp[n][1][3])

if __name__ == "__main__":
    solve()
