H, W, N = map(int, input().split())
a = []
for _ in range(H):
    a.append(list(map(int, input().split())))

# Compute 2D prefix sums
prefix = [[0] * (W + 1) for _ in range(H + 1)]
for i in range(H):
    for j in range(W):
        prefix[i + 1][j + 1] = prefix[i + 1][j] + prefix[i][j + 1] - prefix[i][j] + a[i][j]

# DP table: dp[l][r][k] = maximum minimum sum for submatrix from row l to r with k siblings
# We'll use bottom-up DP to avoid recursion limits

dp = [[[0] * (N + 1) for _ in range(W)] for _ in range(H)]

# Base case: single row
for r in range(H):
    for k in range(N + 1):
        if k == 1:
            # One sibling gets the entire row
            dp[r][r][k] = prefix[r + 1][W] - prefix[r][W]
        else:
            dp[r][r][k] = float('inf')  # Can't partition a single row into multiple siblings

# Fill DP table
for l in range(H - 1, -1, -1):
    for r in range(l + 1, H):
        for k in range(2, N + 1):
            # Try all possible top-left rectangles of size i x j
            for i in range(1, r - l + 1):
                for j in range(1, W):
                    # Take rectangle from (l, 0) to (l+i-1, j-1)
                    sum_rect = prefix[l + i][j] - prefix[l][j] - (prefix[l + i][0] - prefix[l][0])
                    # Remaining area: rows l+i to r, columns 0 to W-1
                    dp[l][r][k] = max(dp[l][r][k], min(sum_rect, dp[l + i][r][k - 1]))

            # Try all possible bottom-right rectangles of size (r-l+1) x j
            for j in range(1, W):
                # Take rectangle from (l, W-j) to (r, W-1)
                sum_rect = prefix[r + 1][W] - prefix[r + 1][W - j] - (prefix[l][W] - prefix[l][W - j])
                # Remaining area: rows l to r-j-1, columns 0 to W-j-1
                dp[l][r][k] = max(dp[l][r][k], min(sum_rect, dp[l][r - j][k - 1]))

# The answer is dp[0][H-1][N]
print(dp[0][H - 1][N])
