import sys

def distance(p, q, s_x, s_y):
    """Calculate distance from block (p, q) to store at (s_x, s_y)"""
    if p == s_x:
        # Same row
        return abs(q - s_y)
    elif abs(p - s_x) == 1:
        # Adjacent rows
        return abs(p - s_x) + abs(q - s_y)
    elif abs(p - s_x) == 2:
        # Two rows away
        return 3
    else:
        # More than two rows away
        return abs(p - s_x) + abs(q - s_y)

def solve():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        m, n = map(int, line.strip().split())
        if m == 0 and n == 0:
            break

        s = int(sys.stdin.readline())
        stores = []
        for _ in range(s):
            x, y = map(int, sys.stdin.readline().strip().split())
            stores.append((x, y))

        t = int(sys.stdin.readline())
        max_coverage = 0
        for _ in range(t):
            p, q = map(int, sys.stdin.readline().strip().split())

            # Count blocks covered by placing a store at (p, q)
            coverage = 0
            for x in range(1, m + 1):
                for y in range(1, n + 1):
                    # Find closest store to block (x, y)
                    min_dist = float('inf')
                    closest_store = None
                    for (s_x, s_y) in stores:
                        dist = distance(p, q, s_x, s_y)
                        if dist < min_dist:
                            min_dist = dist
                            closest_store = (s_x, s_y)

                    # Check if block (x, y) is covered by any existing store
                    if min_dist > 0:
                        coverage += 1

            max_coverage = max(max_coverage, coverage)

        print(max_coverage)

solve()
