# Find MST
mst_weight = 0
mst_edges = []

for u, v, w in edges:
    if find(u) != find(v):
        union(u, v)
        mst_weight += w
        mst_edges.append((u, v, w))

# Now, for each edge not in MST, consider cycle with MST
operations = 0

# Create reverse mapping from (u, v) to index
mst_set = set((u, v) for u, v, w in mst_edges)

for i, (u, v, w) in enumerate(edges):
    if (u, v) in mst_set or (v, u) in mst_set:
        continue

    # Find MST edges in the cycle
    # Build adjacency list for MST
    mst_adj = {}
    for u1, v1, w1 in mst_edges:
        if u1 not in mst_adj:
            mst_adj[u1] = []
        if v1 not in mst_adj:
            mst_adj[v1] = []
        mst_adj[u1].append((v1, w1))
        mst_adj[v1].append((u1, w1))

    # Find path from u to v in MST
    # Using BFS to find path
    from collections import deque

    visited = set()
    queue = deque([(u, []), (v, [])])
    parent_path = {}

    found = False
    while queue:
        node, path = queue.popleft()
        if node in visited:
            continue
        visited.add(node)
        path.append(node)

        if node == v:
            found = True
            break

        for neighbor, _ in mst_adj.get(node, []):
            if neighbor not in visited:
                queue.append((neighbor, path[:]))
                parent_path[neighbor] = node

    if not found:
        continue

    # Extract MST edge weights on the path
    current = v
    cycle_mst_weights = []
    while current != u:
        prev = parent_path[current]
        # Find weight of edge between prev and current
        found_edge = None
        for u2, v2, w2 in mst_edges:
            if (u2 == prev and v2 == current) or (u2 == current and v2 == prev):
                found_edge = w2
                break
        if found_edge is None:
            break
        cycle_mst_weights.append(found_edge)
        current = prev

    if not cycle_mst_weights:
        continue

    max_mst_weight = max(cycle_mst_weights)

    if w > max_mst_weight:
        continue

    # Need to increase to > max_mst_weight
    operations += (max_mst_weight + 1 - w)

