def solve():
    # Read the cost matrix
    t = []
    for _ in range(3):
        row = list(map(int, input().split()))
        t.append(row)

    n = int(input())

    # cost[i][j][k] = cost to move k disks from rod i to rod j
    cost = [[[0]*4 for _ in range(4)] for _ in range(4)]  # 1-indexed

    # Base case: moving 1 disk from i to j costs t[i][j]
    for i in range(1, 4):
        for j in range(1, 4):
            if i != j:
                cost[i][j][1] = t[i-1][j-1]

    # DP
    for k in range(2, n+1):
        for i in range(1, 4):
            for j in range(1, 4):
                # If moving from i to j is not allowed (cost is 0), skip
                if i == j:
                    continue
                # Intermediate rod
                for c in range(1, 4):
                    if c != i and c != j:
                        # Move n-1 disks from i to c
                        # Move 1 disk from i to j
                        # Move n-1 disks from c to j
                        cost[i][j][k] = min(
                            cost[i][j][k],
                            cost[i][c][k-1] + t[i-1][j-1] + cost[c][j][k-1]
                        )

    print(cost[1][3][n])

solve()
