def count_correct_percentage(sequence):
    # Count same foot consecutive pairs
    same_foot_pairs = 0
    for i in range(len(sequence) - 1):
        if sequence[i] == 'L' and sequence[i+1] == 'L':
            same_foot_pairs += 1
        elif sequence[i] == 'R' and sequence[i+1] == 'R':
            same_foot_pairs += 1

    # Total steps in sequence
    total_steps = len(sequence)

    # Maximum possible correct percentage
    # For each same foot consecutive pair, we need at least one break
    # So we need to insert at least (same_foot_pairs) breaks
    # After inserting breaks, we need to count the number of correct steps

    # We need to consider the circular nature (sequence repeats)
    # Let's try all possible ways to insert breaks optimally

    # First, let's try the optimal approach: insert breaks between same foot steps
    # and maximize correct steps by spacing differently

    # Count how many times each foot appears
    foot_count = {'L': 0, 'R': 0}
    for ch in sequence:
        if ch in foot_count:
            foot_count[ch] += 1

    # Total steps including breaks
    # We need at least (same_foot_pairs + 1) steps to insert breaks
    total_steps_with_breaks = same_foot_pairs + 1

    # Calculate correct percentage
    correct_steps = 0
    expected = 'L'

    # Try all possible sequences with breaks inserted
    for i in range(total_steps_with_breaks):
        if i == 0:
            # Start with L
            if expected == 'L':
                correct_steps += 1
            expected = 'R'
        elif i % total_steps_with_breaks == 0:
            # Repeat the pattern
            pass
        else:
            # For each position, try to insert the next character
            for ch in ['L', 'R', 'X']:
                if expected == 'L':
                    if ch == 'L':
                        correct_steps += 1
                    elif ch == 'R':
                        expected = 'L'
                elif expected == 'R':
                    if ch == 'R':
                        correct_steps += 1
                    elif ch == 'L':
                        expected = 'R'

    percentage = (correct_steps / total_steps_with_breaks) * 100
    return percentage

# Read input
sequence = input().strip()

# Calculate and print result
print(f"{count_correct_percentage(sequence):.6f}")
