        # Try deleting from b
        delete_from_b = edit_helper(a, b[1:]) + 1

        # Try changing first characters
        change = edit_helper(a[1:], b[1:]) + (0 if a[0] == b[0] else 1)

        result = min(delete_from_a, delete_from_b, change)
        memo[(a, b)] = result
        return result

