def mod_pow(a, b, mod):
    """Modular exponentiation"""
    result = 1
    while b > 0:
        if b & 1:
            result = (result * a) % mod
        a = (a * a) % mod
        b >>= 1
    return result

def mod_inv(a, mod):
    """Fermat's little theorem for modular inverse"""
    return mod_pow(a, mod - 2, mod)

# Precompute factorials and inverse factorials
mod = 10**9 + 7
max_n = 10**5 + 10
fact = [1] * (max_n)
invc = [1] * (max_n)
for i in range(1, max_n):
    fact[i] = (fact[i-1] * i) % mod
    invc[i] = (mod_inv(fact[i], mod) * i) % mod

def C(n, k):
    """Calculate combination n choose k modulo 10^9+7"""
    if n < k or k < 0:
        return 0
    return (fact[n] * invc[k] % mod) * invc[n - k] % mod

N, K = map(int, input().split())
