A.sort()

ans = 0
for i in range(N):
    for j in range(i + 1, N):
        # A[i] is min, A[j] is max
        ans = (ans + A[i] * C(N - i - 1, K - 1) + A[j] * C(j - 1, K - 1)) % mod

print(ans)
