n, k = map(int, input().split())

if n < k:
    print(-1)
elif k > n:
    print(-1)
else:
    # First k characters are distinct
    res = [chr(ord('a') + i) for i in range(k)]

    # After the first k characters, we need to alternate between 'a' and 'b'
    # Start with 'a' after the last distinct character
    res.append('a')
    for i in range(k + 1, n):
        if i % 2 == 0:
            res.append('a')
        else:
            res.append('b')

    print(''.join(res))
