def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def solve(n):
    if n < 4:
        return -1

    # Try different numbers of 4s (smallest composite)
    # We want to maximize the number of summands, so try from many 4s down
    for k in range(n // 4, 0, -1):
        remaining = n - 4 * k

        # Check if remaining can be covered by sum of composites
        # The minimum we can cover remaining is 4, 6, 8, etc.
        # But we need to check if remaining itself is composite
        # Or if we can use more than one composite for the remaining

        # If remaining == 0, we've covered the whole number with 4s
        if remaining == 0:
            return k

        # Check if remaining >= 4 and is composite
        if remaining >= 4 and not is_prime(remaining):
            return k

    return -1

# Read input and process queries
q = int(input())
for _ in range(q):
    n = int(input())
    print(solve(n))
"}

