n = int(input())
moods = input().split()

# Convert to boolean for easier checking
moods_bool = [mood == '1' for mood in moods]

def is_lucky():
    # Check for regular polygons with k vertices
    for k in range(3, n + 1):
        if n % k == 0:
            spacing = n // k

            # Check if there are enough good knights
            if sum(moods_bool) < k:
                continue

            # Check all possible starting positions
            all_good = True
            for i in range(k):
                if not moods_bool[i * spacing % n]:
                    all_good = False
                    break

            if all_good:
                return True

    return False

print("YES" if is_lucky() else "NO")
