import sys

def solve(N, A):
    # DP: dp[i][j][0/1] = max sum up to index i, taking j elements, last taken (0) or not (1)
    # We need to pick exactly floor(N/2) elements
    target = N // 2

    # dp[i][j][0]: max sum up to index i, picked j elements, last element not taken
    # dp[i][j][1]: max sum up to index i, picked j elements, last element taken
    dp = [[[-float('inf')] * 2 for _ in range(target + 1)] for _ in range(N + 1)]
    dp[0][0][0] = 0
    dp[0][0][1] = -float('inf')  # Can't pick any elements at index 0

    for i in range(1, N + 1):
        for j in range(target + 1):
            # Option 1: Don't take element A[i-1]
            dp[i][j][0] = max(dp[i-1][j][0], dp[i-1][j][1])

            # Option 2: Take element A[i-1]
            if j > 0:
                dp[i][j][1] = dp[i-1][j-1][0] + A[i-1]

    return max(dp[N][target][0], dp[N][target][1])


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    N = int(data[0])
    A = list(map(int, data[1:1+N]))

    print(solve(N, A))

if __name__ == "__main__":
    main()
"}

