# Read treasures
x_coords = []
for _ in range(n):
    x, y = map(int, input().split())
    x_coords.append((x, y))

# Read queries
queries = []
for _ in range(m):
    x1, y1, x2, y2 = map(int, input().split())
    queries.append((x1, y1, x2, y2))

# Create events:
# - treasure at y with x
events = []
for idx, (x, y) in enumerate(x_coords):
    events.append((y, 'enter', x, idx))

# - query range [x1, x2] at y1, and exit at y2
temporary_queries = []
for query_idx, (x1, y1, x2, y2) in enumerate(queries):
    events.append((y1, 'query', x1, x2, query_idx))
    events.append((y2, 'exit', x1, x2, query_idx))

events.sort()

# Coordinate compression for x-values
x_set = set()
for (x, _) in x_coords:
    x_set.add(x)
for (x1, x2, _) in queries:
    x_set.add(x1)
    x_set.add(x2)

sorted_x = sorted(x_set)
compressed = {x: i + 1 for i, x in enumerate(sorted_x)}
size = len(sorted_x)

# Fenwick tree implementation
class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 1)

    def update(self, idx, delta=1):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        result = 0
        while idx > 0:
            result += self.tree[idx]
            idx -= idx & -idx
        return result

    def range_query(self, l, r):
