import sys
from collections import defaultdict

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    q = int(next(it))
    edge_fee = defaultdict(int)
    for _ in range(q):
        t = int(next(it))
        v = int(next(it))
        u = int(next(it))
        if t == 1:
            w = int(next(it))
            while v != u:
                if v > u:
                    edge_fee[(v, v >> 1)] += w
                    v >>= 1
                else:
                    edge_fee[(u, u >> 1)] += w
                    u >>= 1
        else:
            # query
            sum_fee = 0
            while v != u:
                if v > u:
                    sum_fee += edge_fee[(v, v >> 1)]
                    v >>= 1
                else:
                    sum_fee += edge_fee[(u, u >> 1)]
                    u >>= 1
            print(sum_fee)

if __name__ == "__main__":
    solve()
"}

