def solve():
    MOD = 10**9 + 7
    N = int(input())
    s = input().strip()

    # dp[i][j] = number of ways to assign values to positions 1..i with the i-th element being the j-th smallest
    dp = [[0] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = 1

    for i in range(2, N + 1):
        # The value at position i-1 must be the k-th smallest among values 1..i-1
        for k in range(1, i):
            # The value at position i must be the j-th smallest among values 1..i
            for j in range(1, i):
                # The inequality between position i-1 and i is given by s[i-2]
                # The value at position i-1 is k
                # The value at position i is j

                if s[i-2] == '<':
                    # We need the (i-1)-th element < i-th element
                    if k < j:
                        dp[i][j] = (dp[i][j] + dp[i-1][k]) % MOD
                else:
                    # We need the (i-1)-th element > i-th element
                    if k > j:
                        dp[i][j] = (dp[i][j] + dp[i-1][k]) % MOD

    answer = sum(dp[N][j] for j in range(1, N+1)) % MOD
    print(answer)

solve()
