def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True


def main():
    import sys
    input = sys.stdin.read()
    data = input.split()

    if not data or data[0] == '':
        return

    N = int(data[0])
    trains = []

    index = 1
    for _ in range(N):
        if index + 2 >= len(data):
            break

        H = int(data[index])
        M = int(data[index+1])
        S = int(data[index+2])
        index += 3

        # Convert to seconds since midnight
        arrival_time = 3600 * H + 60 * M + S

        # Determine halt time
        if is_prime(arrival_time):
            halt_time = 300  # 5 minutes
        elif arrival_time % 2 == 1:
            halt_time = 180  # 3 minutes
        else:
            halt_time = 120  # 2 minutes

        trains.append((arrival_time, arrival_time + halt_time))

    # Sort by start time
    trains.sort()

    # Find maximum number of platforms needed
    platform_count = 0
    for i in range(1, N):
        # If trains[i] starts before trains[i-1] ends, there's overlap
        if trains[i][0] < trains[i-1][1]:
            platform_count += 1

    print(platform_count)

if __name__ == "__main__":
    main()
