def count_paths(k):
    if k == 0:
        return 0
    if k == 1:
        return 3

    # Recursive function to count paths starting at each node
    def dfs(node, depth):
        if depth == k:
            return 1
        # Total paths starting at this node = 1 (just the node) + sum of paths starting at each descendant
        total = 1
        for i in range(2 * (2 ** depth) - 1):
            # Descendant at depth+1, index = node * 2 + 1 to node * 2 + 2
            # Descendant at depth+1, index = node * 2 + 1 or node * 2 + 2
            if node * 2 + 1 < 2 ** k - 1:
                total += dfs(node * 2 + 1, depth + 1)
            if node * 2 + 2 < 2 ** k - 1:
                total += dfs(node * 2 + 2, depth + 1)
        return total

    total_paths = 0
    for node in range(2 ** k - 1):
        total_paths += dfs(node, 0)
    return total_paths

k = int(input())
MOD = 10**9 + 7
print(count_paths(k) % MOD)

