import sys

def solve():
    # Read all lines from stdin
    lines = sys.stdin.read().strip().split('\n')

    # Build comparison graph
    graph = {
        'A': set(),
        'B': set(),
        'C': set()
    }

    for line in lines:
        if '>' in line:
            heavier, lighter = line[0], line[2]
            graph[heavier].add(lighter)
        elif '<' in line:
            lighter, heavier = line[0], line[2]
            graph[lighter].add(heavier)
        else:
            # Invalid comparison
            print("Impossible")
            return

    # Check for cycles using topological sort
    # We can use Kahn's algorithm for topological sorting
    in_degree = {k: 0 for k in graph}

    # Build adjacency list
    adj = {k: [] for k in graph}
    for heavier in graph:
        for lighter in graph[heavier]:
            adj[heavier].append(lighter)
            in_degree[lighter] += 1

    # Kahn's algorithm
    queue = [node for node in graph if in_degree[node] == 0]
    top_order = []

    while queue:
        node = queue.pop(0)
        top_order.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If topological sort includes all 3 nodes, it's possible
    if len(top_order) == 3:
        # Output in increasing order of weights
        # The order in topological sort is from lightest to heaviest
        # We need to reverse it to get increasing order
        print(''.join(top_order[::-1]))
    else:
        print("Impossible")

if __name__ == '__main__':
    solve()
