# Function to calculate combinations using Lucas' theorem

def lucas_comb(n, k, p):
    if k == 0:
        return 1
    n_mod = n % p
    k_mod = k % p
    if k_mod > n_mod:
        return 0
    # Use Fermat's theorem for small numbers
    return lucas_comb(n // p, k // p, p) * pow(k_mod, p - 2, p) * pow(k_mod - n_mod, p - 2, p) * pow(n_mod, 1, p) % p

# Actually, I need to implement Lucas' theorem properly

# Lucas' theorem: C(n, k) mod p = product of C(n_i, k_i) mod p where n_i = n_i mod p and k_i = k_i mod p

def lucas_comb(n, k, p):
    if k == 0:
        return 1
    n_mod = n % p
    k_mod = k % p
    if k_mod > n_mod:
        return 0
    return lucas_comb(n // p, k // p, p) * comb(n_mod, k_mod, p) % p

