import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    H = int(data[0])
    W = int(data[1])

    grid = []
    idx = 2
    for _ in range(H):
        grid.append(data[idx])
        idx += 1

    # Mouse starts at (0,0), which has a berry
    berries = 1 if grid[0][0] == '*' else 0
    i, j = 0, 0

    while i < H - 1 or j < W - 1:
        # Look at east path (right)
        east_berry = 0
        # All cells (i, j) to (i, W-1)
        for k in range(j, W):
            if grid[i][k] == '*':
                east_berry += 1

        # Look at south path (down)
        south_berry = 0
        # All cells (i, j) to (H-1, j)
        for k in range(i, H):
            if grid[k][j] == '*':
                south_berry += 1

        if east_berry >= south_berry:
            # Go east
            j += 1
        else:
            # Go south
            i += 1

    print(berries)

if __name__ == "__main__":
    solve()
"}

