import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    try:
        xp0 = int(next(it))
        yp0 = int(next(it))
        xp1 = int(next(it))
        yp1 = int(next(it))
        q = int(next(it))
    except StopIteration:
        return
    for _ in range(q):
        try:
            xp2 = int(next(it))
            yp2 = int(next(it))
        except StopIteration:
            break
        dx1 = xp1 - xp0
        dy1 = yp1 - yp0
        dx2 = xp2 - xp0
        dy2 = yp2 - yp0
        cross = dx1 * dy2 - dy1 * dx2
        if cross > 0:
            print("COUNTER_CLOCKWISE")
        elif cross < 0:
            print("CLOCKWISE")
        else:
            # colinear
            dot0 = dx2 * dx1 + dy2 * dy1
            if dot0 < 0:
                print("ONLINE_BACK")
            elif dot0 > 0:
                print("ONLINE_FRONT")
            else:
                print("ON_SEGMENT")

if __name__ == "__main__":
    solve()
"}

