def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    k = n // 2

    # dp[i][j]: max sum considering first i elements, selecting j elements
    # We can use 1D DP to save space
    dp = [-float('inf')] * (k + 1)
    dp[0] = 0

    for i in range(n):
        if i == 0:
            for j in range(1, k + 1):
                dp[j] = -float('inf')
            continue

        new_dp = dp.copy()
        for j in range(1, k + 1):
            # If we select a[i], we must have selected j-1 elements from the first i-2 elements
            if i >= 2:
                new_dp[j] = max(new_dp[j], dp[j-1] + a[i])
        dp = new_dp

    print(dp[k])

if __name__ == "__main__":
    solve()
