    if not data:
        return
    # Read 3x3 matrix
    t = [[0, 0, 0] for _ in range(4)]  # 1-indexed
    idx = 0
    for i in range(1, 4):
        for j in range(1, 4):
            t[i][j] = int(data[idx])
            idx += 1
    n = int(data[idx])

    # DP: dp[n][i][j] = min cost to move n disks from i to j
    dp = [[0 for _ in range(4)] for _ in range(41)]  # 1..3 for i,j, 0..40 for n

    # Base case: n=1
    for i in range(1, 4):
        for j in range(1, 4):
            if i != j:
                dp[1][i][j] = t[i][j]

    # Fill DP
    for move_n in range(2, n + 1):
        for src in range(1, 4):
            for dst in range(1, 4):
                if src == dst:
                    dp[move_n][src][dst] = 0
