                # Move n-1 disks from src -> inter
                # Move 1 disk from src -> dst
                # Move n-1 disks from inter -> dst
                dp[move_n][src][dst] = dp[move_n - 1][src][inter] + t[src][dst] + dp[move_n - 1][inter][dst]

    print(dp[n][1][3])

