import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    # Read 3x3 matrix
    t = [[0] * 3 for _ in range(3)]  # 0-indexed rods 0,1,2
    idx = 0
    for i in range(3):
        for j in range(3):
            t[i][j] = int(data[idx])
            idx += 1
    n = int(data[idx])

    # DP: dp[n][i][j] = min cost to move n disks from i to j
    dp = [[0 for _ in range(4)] for _ in range(41)]  # n=0..40, i=0..3, j=0..3

    # Base case: n=1
    for i in range(3):
        for j in range(3):
            if i != j:
                dp[1][i][j] = t[i][j]

    # Fill DP
    for move_n in range(2, n + 1):
        for src in range(3):
            for dst in range(3):
                if src == dst:
                    dp[move_n][src][dst] = 0
                    continue
