                if maze[i][j] == 'S':
                    entrance = (i, j)
                elif maze[i][j] == 'G':
                    exit = (i, j)

        # Directions: 0=north, 1=east, 2=south, 3=west
        dir_map = [(0, 1), (1, 0), (0, -1), (-1, 0)]

