            state = (r, c, d, cmd_idx)
            if state in visited:
                continue
            visited.add(state)

            if (r, c) == exit:
                print("Yes")
                break

            if cmd_idx < N:
                # Use next command
                turn = commands[cmd_idx]
                if turn == 'L':
                    new_d = (d - 1) % 4
                else:  # R
                    new_d = (d + 1) % 4

                # Move forward as long as possible
                new_r, new_c = r, c
                while True:
                    dr, dc = dir_map[new_d]
                    nr = r + dr
                    nc = c + dc
                    if 0 <= nr < H and 0 <= nc < W and maze[nr][nc] != '#':
