def can_divide(grid, H, W, N, min_value):
    # This function checks if we can divide the grid into N non-overlapping rectangles,
    # each with sum >= min_value

    # Convert to 1D index
    cells = [(i, j) for i in range(H) for j in range(W)]

    # Memoization cache
    from functools import lru_cache

    # Convert grid to 1D for easier access
    flat = [grid[i][j] for i in range(H) for j in range(W)]

    @lru_cache(maxsize=None)
    def dfs(pos, count, used):
        # pos: current position to consider
        # count: number of rectangles formed so far
        # used: set of used indices

        if count == N:
            return True  # We've formed enough rectangles

        # Try to form a rectangle starting from pos
        i, j = cells[pos]

        # Try different bottom-right corners
        for x in range(i, H):
            for y in range(j, W):
                # Calculate sum of rectangle from (i, j) to (x, y)
                rect_sum = 0
                for a in range(i, x+1):
                    for b in range(j, y+1):
                        if (a, b) in used:
                            return False  # Can't use already used cells
                        rect_sum += grid[a][b]

                # Check if this rectangle is valid
                if rect_sum >= min_value:
                    new_used = used.copy()
                    for a in range(i, x+1):
                        for b in range(j, y+1):
                            new_used.add((a, b))

                    if dfs(pos + len(new_used) - len(used), count + 1, new_used):
                        return True
        return False

    return dfs(0, 0, set())

