    for _ in range(N):
        P = int(data[idx]); idx += 1
        T = int(data[idx]); idx += 1
        V = int(data[idx]); idx += 1
        runners.append((P, T, V))

    results = []

    for i, (P, T, V) in enumerate(runners):
