        probs = [P / 100.0 for _ in range(M)]
        resting_times = [T for _ in range(M)]

        dp = [defaultdict(float) for _ in range(M + 1)]
        dp[0][0] = 1.0

        for k in range(M):
            cur = dp[k]
            next_dp = dp[k + 1]
            for rest_time, prob in cur.items():
                next_dp[rest_time] += prob * (1.0 - probs[k])
                next_dp[rest_time + resting_times[k]] += prob * probs[k]

        finish_times = defaultdict(float)
        for rest_time, prob in dp[M].items():
            finish_times[running_time + rest_time] += prob

        results.append(finish_times)

    winning_probabilities = [0.0] * N

    for i in range(N):
        runner_times = results[i]

        for finish_time, prob in runner_times.items():
            prob_all_later = 1.0
            for j in range(N):
