    # Map from stop to its dp value
    dp = {}
    dp[0] = 1

    # Fenwick Tree for range sum queries on defined indices
    # We'll use a dictionary to store non-zero values
    # And keep a sorted list of defined indices for binary search
    defined = [0]
    defined_dict = {0: dp[0]}

    def update(pos, val):
        # Add val to dp[pos]
        if pos in defined_dict:
            defined_dict[pos] = (defined_dict[pos] + val) % MOD
        else:
            defined_dict[pos] = val
        # Insert into sorted list
        left, right = 0, len(defined)
        while left < right:
            mid = (left + right) // 2
            if defined[mid] < pos:
                left = mid + 1
            else:
                right = mid
        defined.insert(left, pos)

    def query_sum(l, r):
        # Sum of dp in [l, r]
        left, right = 0, len(defined)
        # Find index of first value >= l
        while left < right:
            mid = (left + right) // 2
            if defined[mid] < l:
                left = mid + 1
            else:
                right = mid
        # Find index of first value > r
        left2, right2 = 0, len(defined)
        while left2 < right2:
            mid = (left2 + right2) // 2
            if defined[mid] <= r:
                left2 = mid + 1
            else:
                right2 = mid
        return (defined_dict[defined[left2]] - defined_dict[defined[left-1]]) % MOD if left > 0 else defined_dict[defined[left2]] % MOD

    for s, t in buses:
        if t > n or t == 0:
            continue
        # dp[t] = sum of dp[s..t-1]
        # We need to find sum of dp values in the range [s, t-1]
        if s == 0:
            contrib = query_sum(0, t-1)
        else:
            contrib = query_sum(s, t-1)
        dp[t] = contrib
        update(t, contrib)

    print(dp.get(n, 0) % MOD)

if __name__ == "__main__":
    solve()

