def simulate(n, m, floors):
    # floors is a list of strings, with floors[0] being the top floor
    # We start at (n-1, 0) looking right
    row, col = n-1, 0
    direction = 1  # 1 for right, -1 for left
    time = 0

    # We need to track which cells have been broken
    broken_cells = [[False]*m for _ in range(n)]

    while True:
        # Check if we've reached the first floor
        if row == 0:
            return time

        # Check if the cell directly under is empty
        if 0 <= row-1 < n and 0 <= col < m:
            if floors[row-1][col] == '.' and not broken_cells[row-1][col]:
                # Fall down
                row -= 1
                continue

        # Consider next cell in current direction
        next_row, next_col = row, col + direction

        if 0 <= next_col < m:
            if floors[row][next_col] == '.':
                # Move into empty cell
                col = next_col
            elif floors[row][next_col] == '+':
                # Break bricks
                broken_cells[row][next_col] = True
                direction *= -1
            elif floors[row][next_col] == '#':
                # Wall, just change direction
                direction *= -1
        else:
            # Out of bounds, try the other direction
