import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    X = set(map(int, data[1:1+n]))
    s = 106

    if n == 1:
        if s not in X:
            print(1)
            print(s)
        else:
            print(1)
            print(s-1)
        return

    n_x = len(X)
    sum_x = sum(X)

    # Try different values of m (size of Y)
    for m in range(1, n_x + 1):
        required_sum = m * (sum_x - s) / (n_x - 1)
        if required_sum.is_integer():
            required_sum = int(required_sum)
            break
    else:
        # Try m = n_x
        required_sum = n_x * (sum_x - s) / (n_x - 1)
        if required_sum.is_integer():
            required_sum = int(required_sum)
        else:
            # Try m = 1
            required_sum = 1 * (sum_x - s) / (n_x - 1)
            if required_sum.is_integer():
                required_sum = int(required_sum)
            else:
                # Try m = n_x - 1
                required_sum = (n_x - 1) * (sum_x - s) / (n_x - 1)
                required_sum = sum_x - s

    # Now find m numbers not in X that sum to required_sum
    available = [y for y in range(1, s + 1) if y not in X]

    if required_sum >= 0:
        # Pick largest numbers
        available.sort(reverse=True)
        Y = available[:m]
    else:
        # Pick smallest numbers
        available.sort()
        Y = available[:m]

    # Check if we got the right sum
    while sum(Y) != required_sum:
        if required_sum > sum(Y):
            # Need larger numbers
            if available:
                largest = available.pop()
                Y.append(largest)
        elif required_sum < sum(Y):
            # Need smaller numbers
            if available:
                smallest = available.pop(0)
                Y.append(smallest)
        else:
            break

    # Output
    sys.stdout.write(f"{len(Y)}\n")
    sys.stdout.write(" ".join(map(str, Y)) + "\n")

if __name__ == "__main__":
    solve()
