import sys

def compute_f(arr):
    m = len(arr)
    if m == 1:
        return arr[0]
    # Build next level array
    next_arr = []
    for i in range(m - 1):
        next_arr.append(arr[i] ^ arr[i + 1])
    return compute_f(next_arr)

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    q = int(sys.stdin.readline())
    queries = []
    for _ in range(q):
        l, r = map(int, sys.stdin.readline().split())
        queries.append((l, r))

    # Precompute f values for all subsegments
    max_f = [0] * n
    for i in range(n):
        for j in range(i, n):
            sub = a[i:j + 1]
            f_val = compute_f(sub)
            if f_val > max_f[i]:
                max_f[i] = f_val

    # Process queries
    for l, r in queries:
