import sys

def compute_f(arr):
    m = len(arr)
    if m == 1:
        return arr[0]
    # Build next level array
    next_arr = []
    for i in range(m - 1):
        next_arr.append(arr[i] ^ arr[i + 1])
    return compute_f(next_arr)

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    q = int(sys.stdin.readline())
    queries = []
    for _ in range(q):
        l, r = map(int, sys.stdin.readline().split())
        queries.append((l, r))

    # Precompute maximum f value for each starting index
    max_f = [0] * n
    for i in range(n):
        current_max = 0
        sub = []
        for j in range(i, n):
            sub.append(a[j])
            f_val = compute_f(sub)
            if f_val > current_max:
                current_max = f_val
        max_f[i] = current_max

    # Process queries
    for l, r in queries:
        max_val = 0
        for i in range(l - 1, r):
            if max_f[i] > max_val:
                max_val = max_f[i]
        print(max_val)

if __name__ == "__main__":
    solve()

