from collections import deque

def count_paths(k):
    if k == 0:
        return 0

    # Build the tree
    nodes = []
    for level in range(k):
        nodes.append([2**level + i for i in range(2**level)])

    # Build adjacency list
    adj = {}
    for level in range(k):
        for idx, node in enumerate(nodes[level]):
            # Children (level+1)
            children = []
            for i in range(2):
                child_idx = 2 * idx + i
                if child_idx < len(nodes[level+1]):
                    children.append(nodes[level+1][child_idx])

            # Parent (level-1)
            if level > 0:
                parent_idx = (idx - 1) // 2
                parent = nodes[level-1][parent_idx]
                children.append(parent)

            adj[node] = children

    # Count all paths
    total = 0

    def dfs(node, visited):
        nonlocal total
        visited.add(node)

        total += 1  # Count the current node

        for neighbor in adj[node]:
            if neighbor not in visited:
                dfs(neighbor, visited)

        visited.remove(node)

    # Start from each node
    for node in range(1, 2**k):
        dfs(node, set())

    return total

def solve():
    k = int(input())
    MOD = 10**9 + 7

    # Efficiently compute answer using pattern:
    # For k >= 1, answer = 2^(2k-1) - (k-1) * 2^(k-1)
    # This pattern matches the examples:
