import sys

from itertools import combinations

def count_ways(n, coins):
    """Count the number of ways to make n cents using the given coins with unlimited supply"""
    dp = [0] * (n + 1)
    dp[0] = 1

    for coin in coins:
        for i in range(coin, n + 1):
            dp[i] += dp[i - coin]

    return dp[n]

def solve() -> None:
    data = sys.stdin.read().strip().split()

    if not data:
        return

    # First value is N
    n = int(data[0])

    # Remaining values are the coin values
    coins = list(map(int, data[1:]))

    # Generate all subsets of size 1, 2, 3, and 4
    total = 0

    for k in range(1, 5):
        for subset in combinations(coins, k):
            ways = count_ways(n, subset)
            total += ways

    print(total)

if __name__ == "__main__":
    solve()
"}

