h, w = map(int, input().split())
cake = [input().strip() for _ in range(h)]

# Greedy path tracing
i, j = 0, 0
berries = 0

while i < h - 1 or j < w - 1:
    # Count berries in the next square we will move into
    if i+1 < h and j+1 < w:
        down_berry = cake[i+1][j].count('*')
        right_berry = cake[i][j+1].count('*')
    elif i+1 < h:
        down_berry = cake[i+1][j].count('*')
        right_berry = 0
    elif j+1 < w:
        down_berry = 0
        right_berry = cake[i][j+1].count('*')
    else:
        # End point
        break

    if down_berry > right_berry:
        i += 1
    elif right_berry > down_berry:
        j += 1
    else:
        # If equal, prefer right first
        if down_berry > 0:
            i += 1
        else:
            j += 1

# Count berries in the final square
berries += cake[i][j].count('*')

print(berries)
"}

