def is_prime(n):
    """Check if n is prime"""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

# Read input
import sys

n = int(sys.stdin.readline())

trains = []
for _ in range(n):
    h, m, s = map(int, sys.stdin.readline().split())
    x = 3600 * h + 60 * m + s
    trains.append(x)

# Calculate halt times
halt_times = []
for x in trains:
    if is_prime(x):
        halt_times.append(5 * 60)  # 5 minutes in seconds
    elif x % 2 == 1:
        halt_times.append(3 * 60)   # 3 minutes in seconds
    else:
        halt_times.append(2 * 60)   # 2 minutes in seconds

# Sort by arrival time
trains.sort()

# Calculate minimum platforms needed
platforms = 1
last_end_time = trains[0] + halt_times[0]

for i in range(1, n):
    if trains[i] >= last_end_time:
        # No overlap, reuse platform
        last_end_time = trains[i] + halt_times[i]
    else:
        # Need new platform
        platforms += 1
        last_end_time = trains[i] + halt_times[i]

print(platforms)
