import sys

def calculate_area(s, insert_char=None, insert_pos=None):
    """
    Calculate the minimum grid area for sequence s.
    insert_char: optional character to insert at insert_pos.
    insert_pos: optional position where to insert the character.
    """
    if insert_pos is not None and insert_char is not None:
        s = s[:insert_pos] + insert_char + s[insert_pos:]  # Insert the character

    # Track the robot's position
    pos = [0, 0]  # [row, col]

    # Find the range of positions
    min_row = max_row = 0
    min_col = max_col = 0

    for c in s:
        if c == 'W':
            pos[0] -= 1
        elif c == 'S':
            pos[0] += 1
        elif c == 'A':
            pos[1] -= 1
        elif c == 'D':
            pos[1] += 1

        min_row = min(min_row, pos[0])
        max_row = max(max_row, pos[0])
        min_col = min(min_col, pos[1])
        max_col = max(max_col, pos[1])

    return (max_row - min_row + 1) * (max_col - min_col + 1)

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return

    T = int(data[0])
    idx = 1

    for _ in range(T):
        s = data[idx]
        idx += 1

        min_area = calculate_area(s)  # No insertion

        # Try all possible insertions
        for pos in range(len(s) + 1):  # insert at position i
            for c in ['W', 'A', 'S', 'D']:
                area = calculate_area(s, c, pos)
                if area < min_area:
                    min_area = area

        print(min_area)

if __name__ == "__main__":
    solve()
"}

