import sys

def main():
    # Read all input at once
    data = sys.stdin.read().split()

    if not data:
        return

    # Parse input
    n = int(data[0])
    index = 1

    max_time = -1
    best_position = 0

    for _ in range(n):
        t = int(data[index])
        p = int(data[index + 1])
        index += 2

        if t > max_time:
            max_time = t
            best_position = p

    # Determine output based on position
    if best_position > 0:
        print("Left Corner")
    elif best_position < 0:
        print("Right Corner")
    else:
        print("Either Corner")

if __name__ == "__main__":
    main()
"}

